var maxEnvelopes = function(envelopes) {
    const ordered = envelopes.slice().sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        return b[1] - a[1];
    });
    const tails = [];
    for (const [, height] of ordered) {
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < height) lo = mid + 1;
            else hi = mid;
        }
        if (lo === tails.length) tails.push(height);
        else tails[lo] = height;
    }
    return tails.length;
};

